#!/bin/bash
set -euo pipefail

CONFIG_FILE="${SRCROOT}/Ledger/Config.generated.swift"
ENV_FILE="${SRCROOT}/../.env"

# Load .env if present (repo-root .env)
if [ -f "${ENV_FILE}" ]; then
    set -a
    source "${ENV_FILE}"
    set +a
fi

if [ -z "${LEDGER_API_BASE_URL:-}" ]; then
    echo "error: LEDGER_API_BASE_URL is not set."
    echo "note: set it in your shell (export LEDGER_API_BASE_URL=https://...) or create a .env file at the repo root."
    exit 1
fi

cat > "${CONFIG_FILE}" <<EOF
// Auto-generated by Scripts/generate-config.sh. Do not commit, do not edit by hand.
import Foundation

public enum Config {
    public static let apiBaseURL = URL(string: "${LEDGER_API_BASE_URL}")!
}
EOF
